/bin/zsh -lc "python3 -c 'import sys; from typing import Protocol, runtime_checkable; import io
@runtime_checkable
class SupportsRead(Protocol):
 def read(self, length: int = -1, /): ...
class FileProxy:
 def __init__(self): self.stream = io.BytesIO(b\"payload\")
 def __getattr__(self, name): return getattr(self.stream, name)
p = FileProxy()
print(sys.version)
print(\"hasattr:\", hasattr(p, \"read\"), \"protocol:\", isinstance(p, SupportsRead))'"

